package com.pareidolia.incidentmanagement;

import com.pareidolia.incidentmanagement.entity.*;
import com.pareidolia.incidentmanagement.enums.*;
import com.pareidolia.incidentmanagement.repository.*;
import com.pareidolia.incidentmanagement.service.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.oauth2.core.oidc.user.OidcUser;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@DataJpaTest(properties={"app.incident-security-admin.enabled=true","app.incident-access.enabled=true"})
@Import({IncidentSecurityAdministrationService.class,com.pareidolia.incidentmanagement.security.IncidentSecurityGate.class,com.pareidolia.incidentmanagement.security.IncidentReadSnapshot.class})
@Transactional(propagation=Propagation.NOT_SUPPORTED)
class IncidentSecurityAdministrationServiceTests {
    @Autowired JdbcTemplate db; @Autowired AppUserRepository users; @Autowired IncidentRepository incidents;
    @Autowired IncidentSecurityAdministrationService service; @MockitoBean AppUserService authenticated;
    @Autowired jakarta.persistence.EntityManager em; @Autowired org.springframework.transaction.PlatformTransactionManager transactions;
    AppUser actor,target; Incident incident;
    @BeforeEach void setup(){
        db.execute("create table if not exists incident_security_lock(id bigint primary key)");
        if(db.queryForObject("select count(*) from incident_security_lock",Long.class)==0)db.update("insert into incident_security_lock values(1)");
        db.execute("create table if not exists assignment_admin_capabilities(user_id bigint,capability varchar(40),active tinyint,version bigint,primary key(user_id,capability))");
        db.execute("create table if not exists incident_security_classification(incident_id bigint primary key,classification varchar(20),version bigint)");
        db.execute("create table if not exists incident_classification_audit(id bigint generated by default as identity primary key,incident_id bigint,actor_user_id bigint,previous_classification varchar(20),new_classification varchar(20),version bigint,reason varchar(500) check(reason <> 'audit failure'),changed_at timestamp default current_timestamp)");
        db.execute("create table if not exists incident_security_grants(incident_id bigint,user_id bigint,permission varchar(20),active tinyint,version bigint,primary key(incident_id,user_id,permission))");
        db.execute("create table if not exists incident_security_grant_audit(id bigint generated by default as identity primary key,incident_id bigint,target_user_id bigint,permission varchar(20),actor_user_id bigint,old_active tinyint,new_active tinyint,version bigint,reason varchar(500) check(reason <> 'audit failure'),changed_at timestamp default current_timestamp)");
        db.update("delete from incident_classification_audit");db.update("delete from incident_security_grant_audit");db.update("delete from incident_security_classification");db.update("delete from incident_security_grants");db.update("delete from assignment_admin_capabilities");
        actor=account("admin@example.test");target=account("target@example.test");
        incident=new Incident();incident.setIncidentNumber("INC-TEST-"+java.util.UUID.randomUUID());incident.setReportedBy("reporter@example.test");incident.setTitle("Synthetic");incident.setDescription("Synthetic");incident.setIssueType(IssueType.IT_ISSUE);incident.setSeverity(Severity.LOW);incident.setPriority(Priority.LOW);incident=incidents.saveAndFlush(incident);
        db.update("insert into assignment_admin_capabilities values (?,'INCIDENT_CLASSIFIER',1,0),(?,'CASE_ACCESS_ADMIN',1,0)",actor.getId(),actor.getId());
        when(authenticated.getAuthenticatedUser()).thenReturn(actor);var oidc=mock(OidcUser.class);when(oidc.getEmail()).thenReturn(actor.getEmail());when(oidc.getEmailVerified()).thenReturn(true);
        SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(oidc,"",java.util.List.of()));
    }
    AppUser account(String email){var a=users.findByEmail(email).orElseGet(AppUser::new);a.setEmail(email);a.setDisplayName("Synthetic");a.setActive(true);return users.saveAndFlush(a);}
    @AfterEach void clear(){SecurityContextHolder.clearContext();}
    @Test void legacyIncidentStartsUnclassifiedAndClassificationIsVersioned(){
        assertThat(service.triage()).anyMatch(i->i.incidentId()==incident.getId() && i.version()==0);
        assertThat(service.classify(incident.getId(),"RESTRICTED",0L,"Approved").version()).isEqualTo(1);
        assertThatThrownBy(()->service.classify(incident.getId(),"STANDARD",1L,"Downgrade")).isInstanceOf(AccessDeniedException.class);
        db.update("insert into assignment_admin_capabilities values (?,'RESTRICTED_DOWNGRADE',1,0)",actor.getId());
        assertThatThrownBy(()->service.classify(incident.getId(),"STANDARD",0L,"Stale")).isInstanceOf(ResponseStatusException.class);
        assertThat(service.classify(incident.getId(),"STANDARD",1L,"Approved downgrade").version()).isEqualTo(2);
        assertThat(service.classificationHistory(incident.getId())).hasSize(2);
    }
    @Test void grantsRequireSeparateCapabilityAndAuditVersion(){
        assertThat(service.setGrant(incident.getId(),target.getId(),"VIEW",true,0L,"Approved")).isEqualTo(1);
        assertThatThrownBy(()->service.setGrant(incident.getId(),target.getId(),"VIEW",false,0L,"Stale")).isInstanceOf(ResponseStatusException.class);
        assertThat(service.setGrant(incident.getId(),target.getId(),"VIEW",false,1L,"Revoked")).isEqualTo(2);
        assertThat(service.grantHistory(incident.getId(),target.getId(),"VIEW")).hasSize(2);
        assertThatThrownBy(()->service.setGrant(incident.getId(),actor.getId(),"VIEW",true,0L,"Self")).isInstanceOf(AccessDeniedException.class);
        db.update("update assignment_admin_capabilities set active=0 where user_id=? and capability='CASE_ACCESS_ADMIN'",actor.getId());
        assertThatThrownBy(()->service.setGrant(incident.getId(),target.getId(),"HANDLE",true,0L,"No authority")).isInstanceOf(AccessDeniedException.class);
    }
    @Test void auditFailureRollsBackBothOperations(){
        assertThatThrownBy(()->service.classify(incident.getId(),"STANDARD",0L,"audit failure")).isInstanceOf(RuntimeException.class);
        assertThat(db.queryForObject("select count(*) from incident_security_classification where incident_id=?",Long.class,incident.getId())).isZero();
        assertThatThrownBy(()->service.setGrant(incident.getId(),target.getId(),"VIEW",true,0L,"audit failure")).isInstanceOf(RuntimeException.class);
        assertThat(db.queryForObject("select count(*) from incident_security_grants where incident_id=?",Long.class,incident.getId())).isZero();
    }
    @Test void revocationWaitsForAnInFlightAuthorizedMutation() throws Exception {
        service.classify(incident.getId(),"STANDARD",0L,"Classified before access");
        service.setGrant(incident.getId(),target.getId(),"VIEW",true,0L,"Granted");
        service.setGrant(incident.getId(),target.getId(),"MODIFY",true,0L,"Granted");
        var pool=java.util.concurrent.Executors.newFixedThreadPool(2);
        var locked=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);
        Long targetId=target.getId(), incidentId=incident.getId();String targetEmail=target.getEmail(),actorEmail=actor.getEmail();
        try {
            var mutation=pool.submit(()->{
                var oidc=mock(OidcUser.class);when(oidc.getEmail()).thenReturn(targetEmail);when(oidc.getEmailVerified()).thenReturn(true);
                SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(oidc,"",java.util.List.of()));
                try {return new org.springframework.transaction.support.TransactionTemplate(transactions).execute(status->{
                    var account=users.findById(targetId).orElseThrow();var item=incidents.findById(incidentId).orElseThrow();
                    boolean allowed=new com.pareidolia.incidentmanagement.security.IncidentAccessPolicy(em,true).canForMutation(account,item,com.pareidolia.incidentmanagement.security.IncidentAccessPolicy.Permission.MODIFY);
                    locked.countDown();try{if(!release.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("timeout");}catch(InterruptedException ex){Thread.currentThread().interrupt();throw new IllegalStateException(ex);}return allowed;
                });}finally{SecurityContextHolder.clearContext();}
            });
            assertThat(locked.await(5,java.util.concurrent.TimeUnit.SECONDS)).isTrue();
            var revocation=pool.submit(()->{
                var oidc=mock(OidcUser.class);when(oidc.getEmail()).thenReturn(actorEmail);when(oidc.getEmailVerified()).thenReturn(true);
                SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(oidc,"",java.util.List.of()));
                try{return service.setGrant(incidentId,targetId,"MODIFY",false,1L,"Revoked");}finally{SecurityContextHolder.clearContext();}
            });
            assertThatThrownBy(()->revocation.get(300,java.util.concurrent.TimeUnit.MILLISECONDS)).isInstanceOf(java.util.concurrent.TimeoutException.class);
            release.countDown();assertThat(mutation.get(5,java.util.concurrent.TimeUnit.SECONDS)).isTrue();assertThat(revocation.get(5,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(2L);
            var targetOidc=mock(OidcUser.class);when(targetOidc.getEmail()).thenReturn(targetEmail);when(targetOidc.getEmailVerified()).thenReturn(true);
            SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(targetOidc,"",java.util.List.of()));
            Boolean allowed=new org.springframework.transaction.support.TransactionTemplate(transactions).execute(status -> new com.pareidolia.incidentmanagement.security.IncidentAccessPolicy(em,true).canForMutation(users.findById(targetId).orElseThrow(),incidents.findById(incidentId).orElseThrow(),com.pareidolia.incidentmanagement.security.IncidentAccessPolicy.Permission.MODIFY));
            assertThat(allowed).isFalse();
        } finally {release.countDown();pool.shutdownNow();}
    }
    @Test void targetLookupRequiresCaseAdminAndExcludesInactiveAccounts(){
        assertThat(service.searchTargets("target@")).extracting(IncidentSecurityAdministrationService.CaseTarget::id).contains(target.getId());
        db.update("update app_users set active=false where id=?",target.getId());
        assertThat(service.searchTargets("target@")).isEmpty();
        db.update("update assignment_admin_capabilities set active=0 where user_id=? and capability='CASE_ACCESS_ADMIN'",actor.getId());
        assertThatThrownBy(()->service.searchTargets("target@")).isInstanceOf(AccessDeniedException.class);
    }
    @Test void unverifiedActorCannotClassify(){
        var oidc=mock(OidcUser.class);when(oidc.getEmail()).thenReturn(actor.getEmail());when(oidc.getEmailVerified()).thenReturn(false);
        SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(oidc,"",java.util.List.of()));
        assertThatThrownBy(()->service.classify(incident.getId(),"STANDARD",0L,"Reason")).isInstanceOf(AccessDeniedException.class);
    }
    @Test void inactiveTargetsCannotReceiveGrantsButCanBeRevoked(){
        service.setGrant(incident.getId(),target.getId(),"VIEW",true,0L,"Granted");
        db.update("update app_users set active=false where id=?",target.getId());
        assertThat(service.setGrant(incident.getId(),target.getId(),"VIEW",false,1L,"Revoked")).isEqualTo(2);
        assertThatThrownBy(()->service.setGrant(incident.getId(),target.getId(),"VIEW",true,2L,"No")).isInstanceOf(AccessDeniedException.class);
    }
}
